#!/usr/bin/env node
/*
 * EXPERIMENT, not part of the engine. Rerun of Kundali 892 with every engine update to round 12. The true answers were known when this
 * was written, so it is not a test. To keep the analyst out of the evidence as far as possible, the evidence for each hypothesis is
 * GENERATED by one fixed procedure from the chart, fixed before the run:
 *   For each chain house h of a hypothesis, counted from the Lagna,
 *     lordship   every lordship of the lord of h from the Lagna, and h itself from the Moon, typed lordship, side by the owner's classes,
 *                counted from the subject house when the hypothesis has one (from)
 *     occupants  a natural benefic occupant is a role for, a natural malefic occupant is a harm against
 *     aspects    every planet that aspects h, typed aspect, side by natural nature, nodes aspect 5 7 9
 *   For each karaka of the hypothesis a role for.
 *   For each planet that entered by the lines above, a weakness against when any of these holds, D1 sign enemy or debilitated, combust,
 *   in house 6 8 12 from the Lagna, D9 sign enemy or debilitated, subject varga house not kendra trikona 2 or 11.
 * Every piece of evidence is attached to the option named by the hypothesis. A hypothesis is ordered, the lower option has no evidence,
 * and the higher option holds if its strength share is above 50. The choices of chain houses and of the options are the engine author's
 * and are printed first.
 *
 * DISCLOSURE. The first run used the procedure exactly as written above and every hypothesis scored under 50. Looking at the
 * evidence table showed a logic fault in that procedure, a weakness was added for every involved planet, including malefic aspectors. A weak
 * malefic does less harm, which its smaller weight already shows, it does not add a case against. The owner's example concerns a weak
 * CARRIER, a planet that speaks for the option and is itself weak. So the second view, carriers only, adds a weakness only for a
 * planet that has at least one entry for the option. This fix was made after seeing the first output. Both views are printed.
 */
const { tally, naturalNature } = require("../tools/strength_tally");
const { analyse } = require("../tools/planet_strength");
const { scan } = require("../tools/window_scan");
const { nature } = require("../tools/functional_nature");
const { loadVedicCore } = require("../tools/vednetra_loader");
const fs = require("fs"), path = require("path");
const KB = JSON.parse(fs.readFileSync(path.join(__dirname, "..", "data", "significations.json"), "utf8"));
const C = { gender: "female", date: "1993-01-06", time: "07:10:00", tz: 5.5, lat: 27.1333, lon: 81.9667, asOf: "2026-11-13" };
const VC = loadVedicCore();
const chart = VC.avEngineFor({ name: "x", gender: C.gender, birthISO: C.date + "T" + C.time, tz: C.tz, lat: C.lat, lon: C.lon, place: "" }).chart;
const P = chart.planetsByName, LAG = chart.ascendant.sign, MOON = P.Moon.sign;
const signLord = sg => Object.keys(KB.ownSigns).find(p => KB.ownSigns[p].indexOf(sg) >= 0);
const lordshipsFromLagna = pl => KB.ownSigns[pl].map(sg => ((sg - LAG + 12) % 12) + 1).sort((a, b) => a - b);
const ASP = { Sun: [7], Moon: [7], Mercury: [7], Venus: [7], Mars: [4, 7, 8], Jupiter: [5, 7, 9], Saturn: [3, 7, 10], Rahu: [5, 7, 9], Ketu: [5, 7, 9] };
const houseFrom = (a, b) => ((a - b + 12) % 12) + 1;
const nat = naturalNature(C).nat;
const ALL = ["Sun", "Moon", "Mars", "Mercury", "Jupiter", "Venus", "Saturn", "Rahu", "Ketu"];

let CARRIERS_ONLY = false, SUMMARY = false;
function build(h) {
  const base = analyse(Object.assign({}, C, { houses: [], karakas: [], varga: h.varga, candidates: ["Sun", "Moon"] }));
  const ev = [], involved = new Set();
  const add = (e) => { ev.push(Object.assign({ option: h.option }, e)); involved.add(e.planet); };
  h.houses.forEach(hh => {
    const sign = (LAG + hh - 1) % 12, lord = signLord(sign);
    lordshipsFromLagna(lord).forEach(x => add({ type: "lordship", planet: lord, house: x, from: h.from, factor: "lord of house " + hh + " from Lagna, also owns house " + x }));
    const mlord = signLord((MOON + hh - 1) % 12);
    add({ type: "lordship", planet: mlord, house: hh, ref: "moon", from: h.from, factor: "lord of house " + hh + " from Moon" });
    ALL.filter(p => P[p].sign === sign).forEach(p => add(nat[p] === "benefic" ? { type: "role", side: "for", planet: p, factor: "occupies house " + hh + ", natural benefic" } : { type: "harm", side: "against", planet: p, factor: "occupies house " + hh + ", natural malefic" }));
    ALL.filter(p => P[p].sign !== sign && ASP[p].indexOf(houseFrom(sign, P[p].sign)) >= 0).forEach(p => add({ type: "aspect", planet: p, factor: "aspects house " + hh }));
  });
  (h.karakas || []).forEach(k => add({ type: "role", side: "for", planet: k, factor: "karaka" }));
  let carriers = null;
  if (CARRIERS_ONLY) {
    const probe = tally(Object.assign({}, C, { kind: "ordered", options: ["x", h.option], varga: h.varga, evidence: ev.map(e => Object.assign({}, e)) }));
    carriers = new Set(probe.evidence.filter(e => e.side === "for" && e.mult !== 0).map(e => e.planet));
  }
  Array.from(involved).forEach(p => {
    if (p === "Rahu" || p === "Ketu") return;
    if (carriers && !carriers.has(p)) return;
    const r = base.rows[p], why = [];
    if (["Enemy sign", "Debilitated"].indexOf(r.step2.dignity) >= 0) why.push("D1 sign " + r.step2.dignity);
    if (r.step4.combustVednetraFlag) why.push("combust");
    if ([6, 8, 12].indexOf(r.step2.houseFromLagna) >= 0) why.push("house " + r.step2.houseFromLagna);
    if (["Enemy", "Debilitated"].indexOf(r.step3.navamshaDignity) >= 0) why.push("D9 " + r.step3.navamshaDignity);
    if (h.varga && r.step3.topicVarga && !r.step3.topicVarga.inGoodHouse) why.push("D" + h.varga + " house " + r.step3.topicVarga.houseInVarga);
    if (why.length) ev.push({ option: h.option, type: "weakness", side: "against", planet: p, factor: why.join(", ") });
  });
  return ev;
}

function run(title, h, opts) {
  const ev = [].concat.apply([], h.map(build));
  if (SUMMARY) { const t = tally(Object.assign({}, C, { kind: "ordered", options: opts, varga: h[0].varga, evidence: ev })); const r = t.rows; console.log("  " + title.padEnd(44) + t.tallyLine.replace("EVIDENCE TALLY ", "") + "  -> " + t.winner); return t; }
  const t = tally(Object.assign({}, C, { kind: "ordered", options: opts, varga: h[0].varga, evidence: ev }));
  const r = t.rows[opts.length - 1];
  console.log("\n==== " + title);
  console.log("chains " + h.map(x => x.option + " houses " + x.houses.join(",") + (x.from ? " from " + x.from : "") + (x.karakas ? " karakas " + x.karakas.join(",") : "")).join(" | "));
  console.log("evidence entries " + ev.length + ". Per option");
  t.rows.forEach(x => console.log("  " + x.option.padEnd(16) + "favour " + String(x.favour).padEnd(7) + "from " + x.forPlanets.join(", ") + "\n" + " ".repeat(18) + "against " + String(x.against).padEnd(7) + "from " + x.againstPlanets.join(", ") + "  score " + x.score));
  console.log("  " + t.tallyLine + "   -> " + t.winner);
  return t;
}

function allRuns() {
// Education, ordered. 4th house chain gives the Graduation level, 5th and 9th with the karakas give the Post graduation level.
run("Q1 Education", [
  { option: "Graduation", houses: [4], varga: 24 },
  { option: "Post graduation", houses: [5, 9], karakas: ["Mercury", "Jupiter"], varga: 24 }], ["High school", "Intermediate", "Graduation", "Post graduation"]);
run("Q2 Is she married", [{ option: "Married", houses: [7], karakas: ["Venus", "Jupiter"], varga: 9 }], ["Unmarried", "Married"]);
run("Q3 Is she working", [{ option: "Working", houses: [10], karakas: ["Saturn"], varga: 10 }], ["Not working", "Working"]);
run("Q4 Does she have siblings", [{ option: "Has siblings", houses: [3, 11], karakas: ["Mars"], varga: 3 }], ["Only child", "Has siblings"]);
run("Q5 Father alive, houses 9 and 8th from 9th", [{ option: "Alive", houses: [9, 4], from: 9, karakas: ["Sun"], varga: 12 }], ["Not alive", "Alive"]);
run("Q5 Mother alive, houses 4 and 8th from 4th", [{ option: "Alive", houses: [4, 11], from: 4, karakas: ["Moon"], varga: 12 }], ["Not alive", "Alive"]);

}
allRuns();
console.log("\n######## SAME HYPOTHESES, VIEW 2, weakness for carriers only. Scores");
CARRIERS_ONLY = true; SUMMARY = true;
allRuns();
SUMMARY = false;
console.log("\n==== Dasha lords now, Laghu Parashari");
const fn = nature(C);
fn.dasha.forEach(d => console.log("  " + d.level + " " + d.lord + " " + d.from + " to " + d.to + " " + (fn.rows[d.lord] ? fn.rows[d.lord].role : fn.nodes[d.lord].role)));
console.log("\n==== Strict windows with the nodes, Sookshma level");
["marriage", "job_start", "education_step", "sibling_birth", "father_loss", "mother_loss"].forEach(ev => {
  const w = scan(Object.assign({}, C, { event: ev, strict: true })).windows;
  const past = w.filter(x => x.timeStatus !== "FUTURE");
  console.log("  " + ev.padEnd(15) + "past or running " + past.length + ", grade A " + past.filter(x => x.grade === "A").length + ", future " + (w.length - past.length));
});
